const input = $input.first().json;
const incoming = input.body || input;

const cleanDate = (value) => {
  if (!value) return "";
  return String(value).slice(0, 10);
};

const doc = {
  id: incoming.id || incoming.document_number || incoming.html_url || incoming.title || "",
  document_number: incoming.document_number || "",
  title: incoming.title || "",
  agency: incoming.agency || "",
  abstract: incoming.abstract || "",
  document_type: incoming.document_type || incoming.type || "",
  publication_date: cleanDate(incoming.publication_date || incoming.declared_publication_date),
  declared_publication_date: cleanDate(incoming.declared_publication_date || incoming.publication_date),
  source_stream: incoming.source_stream || "federal_register",
  filing_type: incoming.filing_type || "published",
  filing_tag: incoming.filing_tag || "FEDERAL_REGISTER_PUBLISHED",
  status: incoming.status || "published",
  html_url: incoming.html_url || "",
  pdf_url: incoming.pdf_url || "",
  comment_url: incoming.comment_url || "",
  filed_at: incoming.filed_at || "",
  process_after_date: cleanDate(incoming.process_after_date || incoming.publication_date || incoming.declared_publication_date),
  raw_json: incoming.raw_json || incoming
};

return [
  {
    json: doc
  }
];

const doc = $input.first().json;

const animalTerms = [
  "animal","animals","animal welfare","animal health","animal disease","animal testing",
  "laboratory animal","lab animal","humane","livestock","cattle","calves","swine","pig","pigs",
  "pork","poultry","chicken","chickens","turkey","turkeys","sheep","goat","goats","horse","horses",
  "equine","veterinary","veterinarian","wildlife","endangered species","threatened species",
  "marine mammal","migratory bird","fish and wildlife","habitat","zoo","circus","shelter","rescue",
  "dog","dogs","cat","cats","puppy","kitten","slaughter","meat inspection","animal transport",
  "animal handling","aphis","usda aphis","fish and wildlife service","noaa fisheries",
  "zoonotic","zoonosis","aquaculture","fur","trapping","hunting","fishing regulations",
  "habitat destruction","invasive species","animal cruelty","animal rights","factory farm",
  "confinement","gestation crate","battery cage","feedlot","rodeo","trophy hunting"
];

const animalAgencies = [
  "animal and plant health inspection service","aphis","food safety and inspection service","fsis",
  "fish and wildlife service","national marine fisheries service","noaa fisheries",
  "national oceanic and atmospheric administration","agriculture department",
  "u.s. department of agriculture","interior department","food and drug administration","fda","national institutes of health","nih","environmental protection agency","epa"
];

const negativeTerms = [
  "federal reserve","depository institution","reserve requirements","banking",
  "securities and exchange","stock exchange","new york stock exchange",
  "federal energy regulatory commission","adult education","student aid",
  "department of education","nuclear reactor","citric acid","citrate salts", "tin mill",
"steel",
"countervailing duty",
"antidumping",
"tariff",
"imports from china",
"international trade commission",
"investigation nos",
"harmonized tariff schedule"
];

function normalize(text) {
  return String(text || "").toLowerCase().replace(/[^\w\s-]/g, " ").replace(/\s+/g, " ").trim();
}
function escapeRegex(text) {
  return text.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}
function hasTerm(text, term) {
  const normalizedText = normalize(text);
  const normalizedTerm = normalize(term);
  if (!normalizedTerm) return false;
  return new RegExp(`(^|\\W)${escapeRegex(normalizedTerm)}($|\\W)`, "i").test(normalizedText);
}
function countMatches(text, terms) {
  return terms.filter(term => hasTerm(text, term));
}

const titleText = normalize(doc.title);
const abstractText = normalize(doc.abstract);
const agencyText = normalize(doc.agency);
const mainText = [titleText, abstractText].join(" ");
const fullText = [titleText, abstractText, agencyText, normalize(doc.document_type)].join(" ");

const matchedAnimalTerms = countMatches(mainText, animalTerms);
const matchedAnimalAgencies = countMatches(agencyText, animalAgencies);
const matchedNegativeTerms = countMatches(fullText, negativeTerms);

let relevanceScore = 0;

for (const term of animalTerms) {
  if (hasTerm(titleText, term)) relevanceScore += 45;
  if (hasTerm(abstractText, term)) relevanceScore += 30;
}
if (matchedAnimalAgencies.length > 0) relevanceScore += 15;
if (doc.comment_url) relevanceScore += 10;
if (hasTerm(doc.document_type, "proposed rule")) relevanceScore += 10;
else if (hasTerm(doc.document_type, "rule")) relevanceScore += 5;
if (matchedNegativeTerms.length > 0 && matchedAnimalTerms.length === 0) relevanceScore -= 80;
if (matchedAnimalTerms.length === 0 && matchedAnimalAgencies.length === 0) relevanceScore -= 50;

const isCandidate = relevanceScore >= 50 && matchedAnimalTerms.length > 0;

return [{
  json: {
    ...doc,
    relevance_score: relevanceScore,
    matched_animal_terms: matchedAnimalTerms,
    matched_animal_agencies: matchedAnimalAgencies,
    matched_negative_terms: matchedNegativeTerms,
    filter_status: isCandidate ? "candidate_record_found" : "no_relevant_records",
    should_send_to_ai: isCandidate
  }
}];

const aiResponse = $input.first().json;
const originalItems = $items("Build OpenRouter Request Body1");
const original = originalItems && originalItems.length ? originalItems[0].json : {};

function asText(value) {
  if (value === undefined || value === null) return "";
  if (typeof value === "string") return value;
  return JSON.stringify(value);
}

function getField(content, label) {
  const regex = new RegExp(`^${label}:\\s*(.*)$`, "im");
  const match = String(content || "").match(regex);
  return match ? match[1].trim() : "";
}

if (aiResponse.error) {
  return [{
    json: {
      ...original,
      ai_content: "",
      ai_decision: "OPENROUTER_ERROR",
      processor_status: "OPENROUTER_ERROR",
      error_message: aiResponse.error.message || asText(aiResponse.error),
      openrouter_raw: aiResponse
    }
  }];
}

let content = "";
try {
  content = aiResponse.choices[0].message.content || "";
} catch (error) {
  return [{
    json: {
      ...original,
      ai_content: "",
      ai_decision: "OPENROUTER_ERROR",
      processor_status: "OPENROUTER_ERROR",
      error_message: "OpenRouter response did not contain choices[0].message.content.",
      openrouter_raw: aiResponse
    }
  }];
}

content = String(content)
  .replace(/\*\*/g, "")
  .replace(/\*/g, "")
  .replace(/#{1,6}\s/g, "")
  .trim();

const relevanceStatus = getField(content, "Relevance Status").toUpperCase();
const emailDecisionRaw = getField(content, "Email Decision").toUpperCase();

let decision = "DO_NOT_SEND";
if (relevanceStatus === "RELEVANT" && emailDecisionRaw === "SEND") {
  decision = "SEND";
}

return [{
  json: {
    ...original,
    ai_content: content,
    ai_decision: decision,
    ai_relevance_status: relevanceStatus || "UNKNOWN",
    openrouter_raw: aiResponse
  }
}];

return [{
  json: {
    status: 'UNAUTHORIZED',
    message: 'Invalid or missing FederalPaws webhook secret. Set FEDERALPAWS_WEBHOOK_SECRET and send x-federalpaws-secret with the same value.'
  }
}];

const doc = $input.first().json;
return [{
  json: {
    ...doc,
    ai_content: '',
    ai_decision: 'OPENROUTER_ERROR',
    processor_status: 'OPENROUTER_ERROR',
    error_message: 'OPENROUTER_API_KEY is missing or still set to REPLACE_ME. Create a new OpenRouter key, rotate any exposed key, and set it as an n8n environment variable.',
    openrouter_raw: {}
  }
}];

const doc = $input.first().json;

const prompt = `Input notice:

Filing Tag: ${doc.filing_tag || "FEDERAL_REGISTER_PUBLISHED"}
Title: ${doc.title || "No title"}
Agency: ${doc.agency || "Unknown agency"}
Publication Date: ${doc.publication_date || "Unknown date"}
Document Type: ${doc.document_type || "Unknown type"}
Document Number: ${doc.document_number || "Unknown document number"}
Abstract: ${doc.abstract || "No abstract available"}
Source URL: ${doc.html_url || "No URL available"}
PDF URL: ${doc.pdf_url || "No PDF URL available"}
Comment URL: ${doc.comment_url || "No comment URL available"}
Relevance Score: ${doc.relevance_score || 0}
Matched Animal Terms: ${JSON.stringify(doc.matched_animal_terms || [])}
Matched Animal Agencies: ${JSON.stringify(doc.matched_animal_agencies || [])}

Classify and summarize this notice. Return ONLY this exact format, no markdown, no asterisks, no extra text:

Relevance Status: RELEVANT or NOT_RELEVANT
Email Decision: SEND or DO_NOT_SEND
Type of Action: [Proposed Rule / Final Rule / Notice / Public Comment / Permit / Hearing / Other]
Urgency: [High / Medium / Low]
Advocacy Relevance: [High / Medium / Low]
Deadline Sensitivity: [High / Medium / Low / None]
Title: [title]
Agency: [agency name]
Publication Date: [YYYY-MM-DD]
Document Number: [number]
Summary: [2-3 plain English sentences. No jargon.]
Why It Matters: [1-2 sentences on why animal advocates should care. If not relevant, write: Not applicable.]
Actionability Assessment: [Clearly state whether action is still possible. Informational only.]
Recommended Action: [Public comment / Monitor / No action available / Research further]
Suggested Advocacy Talking Points: [2-3 short bullet-style talking points in plain text]
Deadline: [YYYY-MM-DD or None]
Source: [html_url]
Verification Instructions: Open the official Federal Register source link, confirm the agency, publication date, document number, comment deadline, and action type before taking any advocacy action.

Disclaimer: This represents informational guidance only and not legal advice.`;

const openrouter_request_body = {
  model: "openai/gpt-4o-mini",
  messages: [
    {
      role: "system",
      content: "You classify Federal Register notices for animal advocacy relevance. Be strict. Do not invent relevance. If the notice is not clearly animal-related, return NOT_RELEVANT and DO_NOT_SEND. Return only the requested plain text format."
    },
    {
      role: "user",
      content: prompt
    }
  ],
  temperature: 0,
  max_tokens: 900
};

return [{
  json: {
    ...doc,
    openrouter_request_body
  }
}];
